/* School Positives — fictional, browser-local demonstration. No real authentication. */
'use strict';
const $ = s => document.querySelector(s);
const uid = () => typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : 'demo-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2);
const icons={atom:'<circle cx="12" cy="12" r="1"/><ellipse cx="12" cy="12" rx="10" ry="4"/><ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(60 12 12)"/><ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(120 12 12)"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',award:'<circle cx="12" cy="8" r="5"/><path d="m8 12-1 9 5-3 5 3-1-9"/>',shop:'<path d="M3 9 5 3h14l2 6M3 9a3 3 0 0 0 6 0 3 3 0 0 0 6 0 3 3 0 0 0 6 0M4 12v9h16v-9M9 21v-7h6v7"/>',trophy:'<path d="M7 3h10v5a5 5 0 0 1-10 0ZM7 5H3v2a4 4 0 0 0 5 4m9-6h4v2a4 4 0 0 1-5 4M12 13v5m-5 3h10m-9-3h8v3"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',coin:'<circle cx="12" cy="12" r="9"/><path d="m12 6 4 6-4 6-4-6Z"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8Z"/>',question:'<path d="M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5m0 4h.01"/><circle cx="12" cy="12" r="10"/>',heart:'<path d="m12 21-8-8C-3 5 7-2 12 6c5-8 15-1 8 7Z"/>',flask:'<path d="M9 3h6m-5 0v6L4 19a1.5 1.5 0 0 0 1.5 2h13A1.5 1.5 0 0 0 20 19L14 9V3M7 15h10m-7 3h.1m3-5h.1"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',book:'<path d="M12 5c-4-3-8-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-2-1-6-2-10 1v15"/>',leaf:'<path d="M20 3C6 1 1 10 6 16s15 3 14-13ZM4 21 16 8m-8 9v-6m0 6h7"/>',settings:'<path d="M4 5h16M4 12h16M4 19h16M8 2v6m8 1v6m-6 1v6"/>',undo:'<path d="m7 3-5 5 5 5M2 8h12a7 7 0 0 1 0 14h-3"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.star}</svg>`}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cats=[{id:'effort',name:'Excellent effort',icon:'bolt',desc:'Sticking with a challenging task'},{id:'questions',name:'Great questions',icon:'question',desc:'Curiosity that moves learning forward'},{id:'teamwork',name:'Helping others',icon:'heart',desc:'Supporting a classmate to learn'},{id:'practical',name:'Applying skills',icon:'target',desc:'Using skills with care in any subject'},{id:'progress',name:'Great progress',icon:'target',desc:'Taking a step forward in learning'}];
const tiers=[{name:'Getting started',at:0,colour:'#7492b5',light:'#e3edf8',symbol:'1',title:'Every positive counts',power:'Your effort and kindness make a difference.'},{name:'Positive contributor',at:30,colour:'#578c83',light:'#dbf0e9',symbol:'2',title:'Positive contributor',power:'Your everyday contributions are adding up.'},{name:'Role model',at:75,colour:'#b08740',light:'#f7edcf',symbol:'3',title:'Role model',power:'Your positive habits help others learn.'},{name:'School champion',at:150,colour:'#7d70aa',light:'#eae3f8',symbol:'4',title:'School champion',power:'Your commitment makes our school stronger.'},{name:'Community ambassador',at:300,colour:'#b55773',light:'#f8dfeb',symbol:'5',title:'Community ambassador',power:'A sustained contribution to our school community.'}];
const products=[{id:'pencil',name:'School pencil',desc:'A small reward for a great habit. Choose your colour at the shop.',price:10,stock:40,type:'Small wins',art:'pencil',tone:'peach'},{id:'stickers',name:'Sticker pack',desc:'Three colourful stickers for your notebook, bottle or collection.',price:20,stock:28,type:'Collectibles',art:'stickers',tone:'mint'},{id:'eraser',name:'Space eraser',desc:'A little piece of the universe for your pencil case.',price:30,stock:18,type:'Small wins',art:'eraser',tone:'blue'},{id:'notebook',name:'Notebook',desc:'A fresh home for big ideas, sketches and discoveries.',price:50,stock:16,type:'Save for it',art:'notebook',tone:'pink'},{id:'fidget',name:'Fidget',desc:'A pocket-sized reward. Keep it for a well-earned break.',price:80,stock:10,type:'Save for it',art:'atom',tone:'sand'},{id:'kit',name:'Activity kit',desc:'Try something creative at home. A bigger goal worth saving for.',price:120,stock:6,type:'Big discoveries',art:'kit',tone:'purple'}];
function guardian(tier=0){const t=tiers[tier];return `<div class="recognition-emblem" role="img" aria-label="${t.name} recognition level" style="--level-colour:${t.colour};--level-light:${t.light}">${icon('award')}<span>LEVEL ${tier+1}</span></div>`}
function art(type){let s='';switch(type){case'pencil':s='<g transform="rotate(-34 60 60)"><rect x="47" y="14" width="26" height="82" rx="4" fill="#d7a653"/><path d="M47 96h26l-13 22Z" fill="#e7c9a5"/><path d="m56 111 4 7 4-7" fill="#58465d"/><rect x="47" y="14" width="26" height="16" rx="4" fill="#d89093"/><rect x="47" y="27" width="26" height="9" fill="#d6d6df"/><path d="M54 39v52" stroke="#f4cd7e" stroke-width="5"/></g>';break;case'stickers':s='<g transform="rotate(-14 60 60)"><rect x="18" y="27" width="69" height="75" rx="12" fill="#fff" stroke="#d3dfd9" stroke-width="2"/><circle cx="51" cy="55" r="19" fill="#ddede5"/><path d="m43 39 18 32M32 55h38m-28 17 19-33" stroke="#76aa97" stroke-width="3"/><rect x="27" y="81" width="41" height="6" rx="3" fill="#d8e7de"/></g><g transform="rotate(12 84 76)"><rect x="59" y="56" width="47" height="47" rx="10" fill="#fff" stroke="#e5d5ee" stroke-width="2"/><path d="m83 65 4 9 10 2-8 7 2 10-8-5-9 5 2-10-7-7 10-2Z" fill="#bfa1d9"/></g>';break;case'eraser':s='<path d="m39 75 23-26q14-16 28-4t1 27L69 98Z" fill="#c0a6d4"/><path d="m39 75 30 23-12 15q-4 4-8 1L30 99q-6-5-1-10Z" fill="#a9bfe2"/><ellipse cx="69" cy="60" rx="39" ry="10" fill="none" stroke="#f8d58f" stroke-width="5" transform="rotate(-26 69 60)"/><circle cx="35" cy="28" r="4" fill="#e8ca7c"/><path d="m103 85 3 6 6 2-6 2-3 6-2-6-6-2 6-2Z" fill="#a7b8de"/>';break;case'notebook':s='<g transform="rotate(-11 60 60)"><rect x="28" y="14" width="69" height="94" rx="7" fill="#b88ba8"/><rect x="34" y="14" width="63" height="94" rx="6" fill="#d8afc7"/><path d="M40 14v94" stroke="#b98ba8" stroke-width="3"/><rect x="50" y="37" width="36" height="30" rx="4" fill="#f9eff3"/><path d="M58 47h20m-20 8h14" stroke="#c4a3bf" stroke-width="3"/><rect x="84" y="14" width="4" height="94" fill="#9f759e"/><path d="M31 31h7m-7 17h7m-7 17h7m-7 17h7m-7 17h7" stroke="#f8ecf3" stroke-width="3"/></g>';break;case'atom':s='<circle cx="60" cy="60" r="12" fill="#b29ab7"/><g fill="none" stroke="#c7b076" stroke-width="7"><ellipse cx="60" cy="60" rx="43" ry="17" transform="rotate(-25 60 60)"/><ellipse cx="60" cy="60" rx="43" ry="17" transform="rotate(35 60 60)"/><ellipse cx="60" cy="60" rx="43" ry="17" transform="rotate(95 60 60)"/></g><circle cx="29" cy="34" r="8" fill="#baa5cc"/><circle cx="98" cy="48" r="8" fill="#a4c8bd"/><circle cx="53" cy="101" r="8" fill="#c29a9c"/>';break;default:s='<path d="m22 42 40-17 36 17v57l-38 15-38-16Z" fill="#b6a0d4"/><path d="m22 42 38 14 38-14-36-17Z" fill="#d6c5ec"/><path d="M60 56v58l38-15V42Z" fill="#9d85c1"/><path d="m36 73 6-20 11 12-1 25-16-5Z" fill="#f2e7ff"/><path d="m67 76 6-19 10 10v24l-16 4Z" fill="#cdb9e7"/><path d="m103 20 3 7 8 2-8 3-3 7-2-7-7-3 7-2Z" fill="#c5a8e5"/>';}return `<svg viewBox="0 0 120 120" aria-hidden="true">${s}</svg>`}
function rewardArt(p){return `<div class="reward-art ${p.tone}">${art(p.art)}</div>`}
function initials(name){return name.split(' ').map(n=>n[0]).join('')}
const classes=['7A','7B','8A','8B','9A','9B','10A','10B'];
const teachingGroups=[['7SCI1','Science','7A'],['7ENG1','English','7A'],['8SCI1','Science','8A'],['8MAT1','Mathematics','8A'],['9SCI1','Science','9A'],['9ENG1','English','9A'],['9MAT1','Mathematics','9A'],['9PE1','PE','9A'],['9SCI2','Science','9B'],['10SCI1','Science','10A'],['10ART1','Arts','10A']].map(([id,subject,home])=>({id,subject,home}));
const first=['Alex','Mia','Noah','Aria','Leo','Isla','Theo','Zoe','Eli','Ruby','Finn','Ava'];
const last=['Morgan','Patel','Wilson','Chen','Williams','Taylor','Singh','Walker','Brown','Clarke','Scott','Reid'];
const colourPairs=[['#ece3f5','#9675b1'],['#e6eee8','#799c8a'],['#f6e9df','#b69580'],['#e5eaf6','#8e9fbe'],['#f4e2e9','#bb8c9f'],['#f5efdd','#b39d6e']];
function seed(){const d={version:2,students:[],awards:[],purchases:[],goals:{s48:'notebook'},stock:Object.fromEntries(products.map(p=>[p.id,p.stock])),created:Date.now()};classes.forEach((cls,c)=>{for(let i=0;i<12;i++){let total=18+((i*13+c*21)%143);const catBase=Object.fromEntries(cats.map((cat,k)=>[cat.id,Math.floor(total/5)+(k<total%5?1:0)]));d.students.push({id:`s${c*12+i}`,name:`${first[i]} ${last[(i+c*3)%12]}`,cls,year:parseInt(cls),base:total,spent:Math.floor(total/42)*10,starBase:0,catBase})}});d.students.find(s=>s.id==='s84').name='Luca Morgan';d.students.forEach((s,i)=>{if(i%7===0&&s.id!=='s84')return;for(let j=0;j<2;j++){const date=localDate(Date.now()-(2+j+(i%5))*86400000),group=teachingGroups.filter(g=>g.home===s.cls)[j%Math.max(1,teachingGroups.filter(g=>g.home===s.cls).length)];const outside=j===1&&i%3===0;const subject=group?.subject||'Science',cls=group?.id||`${s.year}SCI2`,cat=cats[(i+j)%cats.length].id;d.awards.push({id:`seed-${i}-${j}`,sid:s.id,cat,amount:outside?2:1,star:false,context:outside?'outside':'lesson',lesson:outside?`outside|${date}|seed-${i}`:`${cls}|${date}|${j+1}`,cls,subject:outside?'Wider school':subject,date,period:String(j+1),location:outside?'School grounds':'',note:outside?'Helped another student feel included.':'Kept working after feedback and improved their work.',time:Date.now()-(2+j+(i%5))*86400000,operator:outside?'Pastoral team':subject==='English'?'Ms Wilson':subject==='Mathematics'?'Mr Patel':'Gary Talbot'})}});return d}
const KEY='stp-school-positives-v2';let data;let storageOK=true;try{data=JSON.parse(localStorage.getItem(KEY));if(!data||data.version!==2)data=seed()}catch{data=seed();storageOK=false}
let state={role:'student',page:'dashboard',student:'s48',cls:'9SCI1',date:new Date().toLocaleDateString('en-CA',{timeZone:'Pacific/Auckland'}),period:'1',selected:new Set(),reason:'effort',search:'',league:'class',leagueClass:'9A',leagueYear:9,leagueMeasure:'students',rewardFilter:'all',badgeFilter:'all',shopStudent:'s48',shopProduct:'notebook',shopSearch:'',lastUnlock:'',certYear:'9',certClass:'all',certStatus:'pending',certTier:'all',certSearch:'',certPreviewKeys:[],outsideSearch:'',outsideStudent:'',outsideReason:'teamwork',outsideAmount:'2',outsideLocation:'School grounds',outsideNote:'',outsideBusy:false,adminRole:'school',adminSubject:'Science',adminYear:'9',filterYear:'all',filterSubject:'all',filterContext:'all',filterFrom:'',filterTo:'',family:'morgan',parentChild:'s48'};
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));storageOK=true}catch{storageOK=false;toast('Browser storage is unavailable. Demo changes last until this page closes.')}}
function student(id=state.student){return data.students.find(s=>s.id===id)}
function earned(s){return s.base+data.awards.filter(a=>a.sid===s.id).reduce((n,a)=>n+a.amount,0)}
function wallet(s){return earned(s)-s.spent-data.purchases.filter(p=>p.sid===s.id).reduce((n,p)=>n+p.price,0)}
function tierIndex(s){return tiers.reduce((n,t,i)=>earned(s)>=t.at?i:n,0)}
function starCount(s){return s.starBase+data.awards.filter(a=>a.sid===s.id&&a.star).length}
function categoryCount(s,id){if(id==='star')return s.starBase*2+data.awards.filter(a=>a.sid===s.id&&a.star).reduce((n,a)=>n+a.amount,0);return s.catBase[id]+data.awards.filter(a=>a.sid===s.id&&a.cat===id).reduce((n,a)=>n+a.amount,0)}
function lessonKey(){return `${state.cls}|${state.date}|${state.period}`}
function lessonAwards(s){return data.awards.filter(a=>a.sid===s.id&&a.lesson===lessonKey())}
function lessonPoints(s){return lessonAwards(s).reduce((n,a)=>n+a.amount,0)}
function lessonStar(){return data.awards.filter(a=>a.lesson===lessonKey()&&a.star)}
function avatar(s,big=false){const c=colourPairs[Number(s.id.slice(1))%6];return `<span class="avatar ${big?'big':''}" style="background:${c[0]};color:${c[1]}">${initials(s.name)}</span>`}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
// Certificates are derived from lifetime points, so shop purchases never remove eligibility.
function certificatePoints(i){return i===0?1:tiers[i].at}
function certificateVenue(i){return i===tiers.length-1?'Whole-school assembly':i===tiers.length-2?'Year assembly':'Class or tutor time'}
function certificateRows(){return data.students.flatMap(s=>tiers.flatMap((t,i)=>earned(s)>=certificatePoints(i)?[{key:s.id+'|'+i,s,t,i,record:(data.certificates||{})[s.id+'|'+i]}]:[]))}
function filteredCertificates(){return certificateRows().filter(r=>(state.certYear==='all'||r.s.year===Number(state.certYear))&&(state.certClass==='all'||r.s.cls===state.certClass)&&(state.certStatus==='all'||(state.certStatus==='printed'?!!r.record:!r.record))&&(state.certTier==='all'||r.i===Number(state.certTier))&&(!state.certSearch||r.s.name.toLowerCase().includes(state.certSearch.toLowerCase()))).sort((a,b)=>a.s.cls.localeCompare(b.s.cls)||a.s.name.localeCompare(b.s.name)||a.i-b.i)}
function certificateOptions(values,current){return values.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(l)}</option>`).join('')}
function certificateCentre(){const rows=filteredCertificates(),pending=rows.filter(r=>!r.record);return heading('Milestone certificates.','Certificates appear automatically when students earn each recognition milestone.','<span class="chip">'+icon('award')+' Student leader tools</span>')+`<div class="card pad certificate-intro"><h2>Recognition that grows with the student</h2><p>Getting started, Positive contributor and Role model: class or tutor time. School champion: year assembly. Community ambassador: whole-school assembly.</p><p class="hint">First-point certificate, then 30, 75, 150 and 300 lifetime points. Thresholds are illustrative for the trial. Printing never spends points.</p></div><div class="certificate-filters card pad"><div class="field"><label for="cert-year">Year group</label><select id="cert-year" data-change="certYear">${certificateOptions([['all','All junior years'],...[7,8,9,10].map(y=>[y,'Year '+y])],state.certYear)}</select></div><div class="field"><label for="cert-class">Tutor group</label><select id="cert-class" data-change="certClass">${certificateOptions([['all','All classes'],...classes.map(c=>[c,c])],state.certClass)}</select></div><div class="field"><label for="cert-tier">Recognition level</label><select id="cert-tier" data-change="certTier">${certificateOptions([['all','All levels'],...tiers.map((t,i)=>[i,t.name])],state.certTier)}</select></div><div class="field"><label for="cert-status">Print status</label><select id="cert-status" data-change="certStatus">${certificateOptions([['pending','Ready to print'],['printed','Printed'],['all','All certificates']],state.certStatus)}</select></div><div class="field"><label for="cert-search">Student name</label><input id="cert-search" data-change="certSearch" value="${esc(state.certSearch)}" placeholder="Find a student"></div></div><div class="section-head"><div><h2>${rows.length} certificates ${state.certStatus==='pending'?'ready to print':'in this view'}</h2><p class="sub">Year 9 is selected as one possible Term 1 trial cohort. Change the filters to explore the demo.</p></div><button class="button" data-action="certBatch" ${pending.length?'':'disabled'}>${icon('award')} Prepare ${pending.length} pending certificates</button></div><p class="hint">Preview, print or save as PDF, then mark printed once printing succeeds. Cancelled prints remain ready. Printed certificates can be reprinted.</p><div class="card table-wrap"><table class="league-table"><thead><tr><th>Student</th><th>Milestone</th><th>Presentation</th><th>Status</th><th>Certificate</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.s.name)}</b><br><small>${r.s.cls} · ${earned(r.s)} lifetime points</small></td><td>${r.t.name}<br><small>${certificatePoints(r.i)} point${certificatePoints(r.i)===1?'':'s'}</small></td><td>${certificateVenue(r.i)}</td><td>${r.record?'Printed '+esc(r.record.date):'Ready to print'}</td><td><button class="button outline" data-action="certPreview" data-value="${r.key}">${r.record?'Preview / reprint':'Preview / print'}</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No certificates match these filters. Certificates appear here automatically as milestones are earned.</div></td></tr>'}</tbody></table></div><p class="hint">Prototype uses fictional students and records print status in this browser only. Assembly presentation follows school approval and arrangements.</p>`}
function certificateMarkup(r){const date=r.record?.date||new Date().toLocaleDateString('en-NZ',{timeZone:'Pacific/Auckland',day:'numeric',month:'long',year:'numeric'});return `<article class="milestone-certificate certificate-v2" style="--metal:${r.t.colour};--metal-light:${r.t.light}"><svg class="certificate-art" viewBox="0 0 1200 848" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="dots-${r.s.id}-${r.i}" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1.1" fill="#001834" opacity=".08"/></pattern><linearGradient id="metal-${r.s.id}-${r.i}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${r.t.light}"/><stop offset="1" stop-color="${r.t.colour}"/></linearGradient></defs><rect width="1200" height="848" fill="#fffdf6"/><rect width="278" height="848" fill="#061d35"/><path d="M0 0h278v848H0" fill="url(#dots-${r.s.id}-${r.i})"/><path d="M0 0h278v22H0" fill="#cc0033"/><path d="m278 0 24 0 0 848-24 0" fill="url(#metal-${r.s.id}-${r.i})"/><path d="M332 40h828v768H332" fill="none" stroke="${r.t.colour}" stroke-width="2"/><path d="M346 54h800v740H346" fill="none" stroke="${r.t.colour}" stroke-width=".7"/><path d="M1040 808h120V688" fill="none" stroke="${r.t.colour}" stroke-width="7"/><path d="M332 158V40h118" fill="none" stroke="${r.t.colour}" stroke-width="7"/></svg><div class="certificate-side-brand">ST PETER’S<span>SCHOOL POSITIVES</span></div><div class="certificate-guardian">${guardian(r.i)}</div><div class="certificate-side-level">LEVEL ${r.i+1}<strong>${r.t.name.toUpperCase()}</strong><span>${r.t.title}</span></div><div class="certificate-topline">ST PETER’S</div><div class="certificate-seal"><b>${r.t.symbol}</b><span>${r.t.name}</span></div><div class="certificate-main"><div class="certificate-subject">CERTIFICATE OF ACHIEVEMENT</div><h2 class="certificate-title">${r.t.name} Award</h2><div class="certificate-small-rule"></div><p class="certificate-awarded">Proudly presented to</p><h3 class="certificate-name">${esc(r.s.name)}</h3><p class="certificate-class">YEAR ${r.s.year} · ${esc(r.s.cls)}</p><p class="certificate-message">For your hard work, curiosity and positive<br>contribution to our school.</p><div class="certificate-milestone">${r.i===0?'FIRST POSITIVE POINT EARNED':certificatePoints(r.i)+' LIFETIME POSITIVE POINTS'}</div></div><div class="certificate-bottom"><div><b>St Peter’s</b><span>Issued ${esc(date)}</span></div><div><b>${certificateVenue(r.i)}</b><span>Certificate ${esc(r.s.id.toUpperCase())}-${r.t.symbol}</span></div></div><div class="certificate-demo">PROTOTYPE · FICTIONAL STUDENT</div></article>`}
function previewCertificates(keys){if(state.role!=='shop')return toast('Use the student leader account to print certificates.');const rows=certificateRows().filter(r=>keys.includes(r.key));if(!rows.length)return toast('No eligible certificates in this selection.');state.certPreviewKeys=rows.map(r=>r.key);modal(rows.length===1?'Certificate preview':rows.length+' certificate previews',`<p>Check names and presentation venues. Use Print / save PDF, then mark printed after successful printing.</p><div class="certificate-previews">${rows.map(certificateMarkup).join('')}</div>`,`<button class="button outline" data-action="printCertificates">Print / save PDF</button><button class="button" data-action="markCertificatesPrinted">Mark ${rows.length} printed</button>`);$('#dialog').classList.add('certificate-dialog')}
function printCertificates(){if(state.role!=='shop')return;const keys=state.certPreviewKeys||[],rows=certificateRows().filter(r=>keys.includes(r.key));if(!rows.length)return;$('#certificate-print-root').innerHTML=rows.map(certificateMarkup).join('');window.print()}
function markCertificatesPrinted(){if(state.role!=='shop')return;const keys=state.certPreviewKeys||[],rows=certificateRows().filter(r=>keys.includes(r.key));data.certificates=data.certificates||{};const date=new Date().toLocaleDateString('en-NZ',{timeZone:'Pacific/Auckland',day:'numeric',month:'long',year:'numeric'});rows.forEach(r=>{if(!data.certificates[r.key])data.certificates[r.key]={date,time:Date.now(),operator:'Student leader team'}});save();$('#dialog').close();render();toast(rows.length+' certificates recorded as printed. Points are unchanged.')}

const navByRole={student:[['dashboard','home','My dashboard'],['rewards','shop','Reward shop'],['achievements','award','Achievements'],['leagues','trophy','The leagues']],teacher:[['teacherDashboard','home','Staff dashboard'],['classroom','users','Award lesson points'],['outside','heart','Out-of-class positives'],['counter','shop','Cash in points'],['leagues','trophy','The leagues'],['guide','book','How it works']],shop:[['counter','shop','Shop counter'],['certificateCentre','award','Certificates'],['rewards','coin','Reward catalogue'],['guide','book','How it works']],admin:[['analytics','target','Recognition analysis'],['outside','heart','Out-of-class positives'],['guide','book','How it works']],parent:[['parentView','heart','My children’s positives'],['guide','book','How it works']]};
const pageNames={certificateCentre:'Certificates',dashboard:'My dashboard',rewards:'Reward shop',achievements:'Achievements',leagues:'The leagues',teacherDashboard:'Staff dashboard',classroom:'Award lesson points',counter:'Shop counter',guide:'How it works',outside:'Out-of-class positives',analytics:'Recognition analysis',parentView:'My children’s positives'};
function render(){const s=student(),labels={student:'Student view',teacher:'Staff view',shop:'Shop counter',admin:'Leader analysis',parent:'Parent view'},pages={dashboard,teacherDashboard,achievements,rewards,leagues,classroom,counter,certificateCentre,guide,outside,analytics,parentView};if(!navByRole[state.role].some(x=>x[0]===state.page)&&state.page!=='guide')state.page=navByRole[state.role][0][0];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('award')}</div><strong>School<br>Positives<small>ST PETER’S</small></strong></div><div class="nav-label">${state.role==='parent'?'YOUR FAMILY':state.role==='student'?'YOUR SCHOOL JOURNEY':'SCHOOL RECOGNITION'}</div><nav class="nav" aria-label="Main navigation">${navByRole[state.role].map(([id,ic,label])=>`<button class="${state.page===id?'active':''}" data-action="nav" data-value="${id}">${icon(ic)}${label}</button>`).join('')}</nav><div class="side-foot"><div class="side-note"><b>Everyday positives matter</b><p>Effort, progress and kindness across school.</p><button class="text-button" data-action="guide">About this prototype</button></div><div class="side-user"><span class="avatar">${state.role==='student'?initials(s.name):state.role==='parent'?'FM':state.role==='admin'?'SL':'ST'}</span><div><b>${state.role==='student'?esc(s.name):labels[state.role]}</b><small>Fictional demo account</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">School Positives / <strong>${pageNames[state.page]}</strong></div><div class="top-actions"><span class="demo-pill">DEMO DATA</span><div class="role-switch" aria-label="Switch demo account">${Object.entries(labels).map(([r,l])=>`<button data-action="role" data-value="${r}" class="${state.role===r?'active':''}" aria-pressed="${state.role===r}">${l}</button>`).join('')}</div></div></header><div class="content">${pages[state.page]()}<div class="banner">${icon('info')}<span>Fictional prototype. Demo roles simulate access, with changes saved ${storageOK?'in this browser only':'temporarily'}. School sign-in and verified family links are required before live use.</span></div><div class="footer-text">ST PETER’S · WHOLE-SCHOOL POSITIVE RECOGNITION</div></div></main></div>`}
function studentPicker(){return `<div class="account-picker"><label for="student-switch">Viewing student</label><select id="student-switch" data-change="student">${data.students.map(s=>`<option value="${s.id}" ${s.id===state.student?'selected':''}>${esc(s.name)} · ${s.cls}</option>`).join('')}</select></div>`}
function heading(title,sub,extra=''){return `<div class="heading"><div><div class="eyebrow">${state.role==='parent'?'FAMILY RECOGNITION':state.role==='admin'?'LEADER ANALYSIS':'ST PETER’S · SCHOOL POSITIVES'}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${extra}</div>`}
function stats(items){return `<div class="stats">${items.map(([ic,label,value,sub])=>`<div class="card stat"><span class="stat-icon">${icon(ic)}</span><div><small>${label}</small><strong>${value}</strong><em>${sub}</em></div></div>`).join('')}</div>`}
