function dashboard(){const s=student(),ti=tierIndex(s),t=tiers[ti],next=tiers[ti+1],goal=products.find(p=>p.id===data.goals[s.id]),badges=getBadges(s),unlocked=badges.filter(b=>b.count>=b.goal),rank=data.students.filter(x=>x.cls===s.cls).sort((a,b)=>earned(b)-earned(a)||a.name.localeCompare(b.name)).findIndex(x=>x.id===s.id)+1;
return heading(`Hi ${esc(s.name.split(' ')[0])}, your positives add up.`,"Every bit of effort adds up. Here’s where your school journey stands.",studentPicker())+`<div class="grid2"><div><div class="hero"><div class="hero-text"><div class="eyebrow">${t.name.toUpperCase()} RECOGNITION · LEVEL ${ti+1}</div><h2>${t.title}</h2><p>${t.power} ${next?`${next.at-earned(s)} more points to reach ${next.name}.`:'You have reached our highest recognition level.'}</p><button class="button" data-action="nav" data-value="achievements">Explore your collection ${icon('arrow')}</button></div>${guardian(ti)}<span class="hero-spark">✧</span><span class="hero-star">✦</span></div>${stats([['coin','Ready to spend',wallet(s),'Your reward shop balance'],['star','Lifetime points',earned(s),'Every positive point counts'],['award','Badges collected',unlocked.length+'<span style="font-size:13px;color:#b0a3ba;letter-spacing:0"> / '+badges.length+'</span>','Your achievements, forever']])}<div class="card pad mb"><div class="section-head"><h2>Your positive moments</h2><span class="chip">${s.cls} · Across school</span></div>${activity(s,5)}</div><div class="card pad"><div class="section-head"><h2>What makes you shine</h2><span class="sub">Points by category</span></div>${breakdown(s)}</div></div><div class="stack"><div class="card pad"><div class="section-head"><h2>Your next milestone</h2>${icon('target')}</div><div class="level-row">${guardian(next?ti+1:ti)}<div class="level-detail"><h3>${next?next.name:'Collection complete'}</h3><span class="sub">${next?'Level '+(ti+2)+' · '+next.at+' lifetime points':'Community ambassador · Level 5'}</span></div></div><div class="between progress-label"><span>${earned(s)} lifetime points</span><span>${next?next.at:'300+'}</span></div><div class="progress"><span style="width:${next?Math.min(100,(earned(s)-t.at)/(next.at-t.at)*100):100}%"></span></div><p class="hint">${next?`Only ${next.at-earned(s)} points to go. Your level stays yours, even when you spend points.`:'All five levels unlocked. Spending never removes them.'}</p><div class="reward-tiny">${goal?rewardArt(goal):'<div class="stat-icon">'+icon('shop')+'</div>'}<div><h4>${goal?'Saving for '+goal.name:'Choose your next reward'}</h4><small>${goal?`${wallet(s)} / ${goal.price} points · ${wallet(s)>=goal.price?'Ready to collect!':(goal.price-wallet(s))+' more to go'}`:'Pick something you would love to earn.'}</small><br><button class="text-button" data-action="nav" data-value="rewards">Visit the reward shop →</button></div></div></div><div class="card pad"><div class="section-head"><h2>A little badge of honour</h2><button class="text-button" data-action="nav" data-value="achievements">View all</button></div><div class="mini-badges">${unlocked.slice(0,3).map(b=>`<div>${badgeToken(b)}<strong>${b.name}</strong><small>Unlocked</small></div>`).join('')}</div></div><div class="card pad"><div class="section-head"><h2>Your class league</h2><span class="chip">#${rank} in ${s.cls}</span></div>${data.students.filter(x=>x.cls===s.cls).sort((a,b)=>earned(b)-earned(a)||a.name.localeCompare(b.name)).slice(0,3).map((x,i)=>`<div class="mini-ranking"><span class="rank-num">0${i+1}</span>${avatar(x)}<strong>${esc(x.name)}${x.id===s.id?' · You':''}</strong><span class="points">${earned(x)} pts</span></div>`).join('')}<button class="text-button mt" data-action="nav" data-value="leagues">Explore the leagues ${icon('arrow')}</button></div></div></div>`}
function breakdown(s){let allCats=[...cats,{id:'star',name:'Star of the Lesson',icon:'star'}];let max=Math.max(...allCats.map(c=>categoryCount(s,c.id)),1);return `<div class="category-breakdown">${allCats.map(c=>`<div class="category-row"><span>${icon(c.icon)} ${c.name}</span><div class="progress"><span style="width:${categoryCount(s,c.id)/max*100}%"></span></div><b>${categoryCount(s,c.id)}</b></div>`).join('')}</div>`}
function activity(s,limit=8,positiveOnly=false){const rows=[...data.awards.filter(a=>a.sid===s.id).map(a=>({...a,type:'award'})),...(positiveOnly?[]:data.purchases.filter(p=>p.sid===s.id).map(p=>({...p,type:'purchase'})))].sort((a,b)=>b.time-a.time);return rows.slice(0,limit).map(a=>{const c=cats.find(c=>c.id===a.cat),purchase=a.type==='purchase',title=purchase?products.find(p=>p.id===a.pid).name+' collected':a.star?'Star of the Lesson':c?.name||'Positive contribution';return `<div class="activity-row"><span class="activity-icon">${icon(purchase?'shop':a.star?'star':c?.icon||'heart')}</span><div><h4>${title}</h4><small>${purchase?'School shop':a.context==='outside'?esc(a.location)+' · Out of class':esc(a.subject)+' · Period '+a.period} · ${when(a.time)}</small>${a.note?`<p>${esc(a.note)}</p>`:''}${!purchase?`<small>Recognised by ${esc(a.operator)}</small>`:''}</div><span class="delta ${purchase?'spend':''}">${purchase?'−'+a.price:'+'+a.amount} pts</span></div>`}).join('')||'<p class="empty">No positive moments recorded yet.</p>'}
function when(time){return new Date(time).toLocaleDateString('en-NZ',{day:'numeric',month:'short',timeZone:'Pacific/Auckland'})}
function achievements(){let s=student(),ti=tierIndex(s),badges=getBadges(s),earnedBadges=badges.filter(b=>b.count>=b.goal),shown=badges.filter(b=>state.badgeFilter==='all'||(state.badgeFilter==='unlocked'?b.count>=b.goal:b.count<b.goal));return heading('A collection earned by you.','Your contributions matter. Build recognition across lessons and the wider school.',studentPicker())+`<div class="section-head"><h2>Whole-school recognition levels</h2><span class="sub">${ti+1} of ${tiers.length} unlocked · based on lifetime points</span></div><div class="guardians">${tiers.map((t,i)=>`<div class="guardian-card ${i>ti?'locked':''} ${i===ti?'current':''}">${guardian(i)}<h3>${t.name}</h3><p>Level ${i+1} · ${t.at} points</p><p class="certificate-venue">Certificate: ${certificateVenue(i)}${i===0?' (first earned point)':''}</p><span class="status">${i>ti?icon('lock')+' '+(t.at-earned(s))+' points to go':i===ti?'YOUR CURRENT LEVEL':'✓ COLLECTED'}</span></div>`).join('')}</div><div class="section-head"><h2>Your achievements <span class="sub">${earnedBadges.length} / ${badges.length}</span></h2><div class="tabs">${[['all','All badges'],['unlocked','Unlocked'],['locked','To discover']].map(([v,l])=>`<button class="${state.badgeFilter===v?'active':''}" data-action="badgeFilter" data-value="${v}">${l}</button>`).join('')}</div></div><div class="badge-grid">${shown.map(b=>`<div class="card achievement ${b.count<b.goal?'locked':''}">${badgeToken(b)}<h3>${b.name}</h3><p>${b.desc}</p>${b.count>=b.goal?'<span class="earned">'+icon('check')+' Unlocked — yours to keep</span>':`<div class="between progress-label"><span>Keep going</span><span>${Math.min(b.count,b.goal)} / ${b.goal}</span></div><div class="progress"><span style="width:${Math.min(100,b.count/b.goal*100)}%"></span></div>`}</div>`).join('')||'<div class="empty">All caught up! Every badge in this collection is unlocked.</div>'}</div><p class="hint">Recognition levels and badges unlock automatically. Shop purchases never remove your level or earned achievements.</p>`}
function rewards(){const s=student(),isStudent=state.role==='student',balance=wallet(s),shown=products.filter(p=>state.rewardFilter==='all'||(state.rewardFilter==='affordable'?p.price<=balance:p.price>balance));return heading('Good habits. Great rewards.',isStudent?'Spend a little or save for something bigger. Your next milestone is up to you.':'Example prizes and prices for the lunchtime school shop.',isStudent?`<span class="chip">${icon('coin')} ${balance} points to spend</span>`:'<span class="chip">Example reward catalogue</span>')+`<div class="league-hero"><span>${icon('shop')}</span><div><h3>A real shop. A reward you’ve earned.</h3><p>Choose a goal here, then visit the school shop at lunchtime. The shop team checks your balance and takes the points when you collect.</p></div></div>${isStudent?`<div class="toolbar"><div class="tabs">${[['all','All rewards'],['affordable','I can afford'],['saving','Save for later']].map(([v,l])=>`<button data-action="rewardFilter" data-value="${v}" class="${state.rewardFilter===v?'active':''}">${l}</button>`).join('')}</div><span class="spacer"></span><span class="sub">Your badges &amp; levels are yours to keep.</span></div>`:''}<div class="reward-grid">${shown.map(p=>{const goal=data.goals[s.id]===p.id,stock=data.stock[p.id];return `<article class="card reward-card"><div class="reward-art ${p.tone}"><span class="reward-category">${p.type.toUpperCase()}</span>${art(p.art)}</div><div class="reward-body"><div class="between"><h3>${p.name}</h3>${goal&&isStudent?'<span class="goal-tag">MY GOAL</span>':''}</div><p>${p.desc}</p><div class="between"><span class="points">${icon('coin')}${p.price} points</span><span class="stock">${stock>0?stock+' in the shop':'Out of stock'}</span></div>${isStudent?`<button class="button ${goal?'soft':'outline'}" data-action="goal" data-value="${p.id}" ${stock===0?'disabled':''}>${goal?icon('check')+' Saving for this':balance>=p.price?'Set goal · ready to collect':'Set as my savings goal'}</button>`:`<button class="button outline" data-action="${state.role==='shop'?'shopPick':'prizeInfo'}" data-value="${p.id}">${state.role==='shop'?'Redeem at the counter':'View reward'}</button>`}</div></article>`}).join('')||'<div class="empty">No rewards in this view. Try All rewards.</div>'}</div>`}
function classroom(){const group=lessonGroup(),roster=rosterForLesson(),visible=roster.filter(s=>s.name.toLowerCase().includes(state.search.toLowerCase())),awards=data.awards.filter(a=>a.lesson===lessonKey()),stars=lessonStar(),selected=roster.filter(s=>state.selected.has(s.id)),eligible=selected.filter(s=>!lessonAwards(s).some(a=>!a.star)),canStar=selected.length>0&&selected.length<=2-stars.length&&selected.every(s=>!lessonAwards(s).some(a=>a.star));return heading('Recognise a positive lesson.','One regular point per student, plus two extra for a lesson star.','<button class="button outline" data-action="nav" data-value="outside">Out-of-class recognition</button>')+`<div class="card pad mb"><div class="filters"><div class="field"><label for="class">Teaching group</label><select id="class" data-change="cls">${teachingGroups.map(g=>`<option value="${g.id}" ${g.id===state.cls?'selected':''}>${g.id} · ${g.subject}</option>`).join('')}</select></div><div class="field"><label for="lesson-date">Lesson date</label><input id="lesson-date" type="date" value="${state.date}" data-change="date" required></div><div class="field"><label for="period">Period</label><select id="period" data-change="period">${[1,2,3,4,5,6,7].map(p=>`<option ${String(p)===state.period?'selected':''}>${p}</option>`).join('')}</select></div><span class="chip">1 regular + 2 star = maximum 3</span></div></div><div class="summary-strip"><span><b>${roster.length}</b> students</span><span><b>${awards.reduce((n,a)=>n+a.amount,0)}</b> points this lesson</span><span><b>${stars.length} / 2</b> lesson stars awarded</span></div><div class="grid2 teacher"><div class="card pad"><div class="section-head"><h2>${state.cls} <span class="sub">${group.subject}</span></h2><input type="search" placeholder="Find a student" aria-label="Find a student in class" value="${esc(state.search)}" data-input="rosterSearch"></div><div class="toolbar"><b>${selected.length} selected</b><button class="text-button" data-action="selectAll">Select visible</button><button class="text-button" data-action="clear">Clear</button></div><div class="roster">${visible.map(s=>`<button class="student-card ${state.selected.has(s.id)?'selected':''}" data-action="selectStudent" data-value="${s.id}" aria-pressed="${state.selected.has(s.id)}">${lessonAwards(s).some(a=>a.star)?'<span class="star-mark">★</span>':''}${avatar(s)}<strong>${esc(s.name)}</strong><small>${s.cls} · ${lessonPoints(s)} / 3 lesson points</small><small>${lessonAwards(s).some(a=>!a.star)?'Regular point awarded':'Regular point available'}</small></button>`).join('')||'<p class="empty">No matching students.</p>'}</div><h2 class="mt">Lesson activity</h2>${awards.slice().reverse().map(a=>`<div class="activity-row"><span class="activity-icon">${icon(a.star?'star':cats.find(c=>c.id===a.cat).icon)}</span><div><h4>${esc(student(a.sid).name)}</h4><small>${a.star?'Star of the Lesson':cats.find(c=>c.id===a.cat).name} · +${a.amount} points</small></div><button class="text-button" data-action="undoAward" data-value="${a.id}">Undo</button></div>`).join('')||'<p class="hint">Awards for this lesson appear here.</p>'}</div><aside class="card pad award-panel"><h2>Regular lesson point</h2><p>Choose the reason for recognition.</p><div class="reason-list">${cats.map(c=>`<button class="reason ${state.reason===c.id?'active':''}" data-action="reason" data-value="${c.id}" aria-pressed="${state.reason===c.id}">${icon(c.icon)}${c.name}</button>`).join('')}</div><button class="button" data-action="award" ${eligible.length?'':'disabled'}>Award ${eligible.length||''} student${eligible.length===1?'':'s'} +1</button><p class="hint">One regular point per student per lesson. Students who already have it are skipped.</p><div class="star-box"><h3>${icon('star')} Star of the Lesson</h3><p><b>Two extra points</b> for each selected star. A maximum of <b>two students per lesson</b> can receive a star.</p><button class="button" data-action="star" ${canStar?'':'disabled'}>Award Star of the Lesson +2</button><p>${2-stars.length} star place${2-stars.length===1?'':'s'} left. Select one or two eligible students.</p></div></aside></div>`}
function award(star=false){if(state.role!=='teacher')return toast('Use the staff demo to award lesson points.');if(!state.date||!lessonGroup())return toast('Choose a valid lesson.');const roster=rosterForLesson(),chosen=[...state.selected].map(id=>roster.find(s=>s.id===id)).filter(Boolean);if(!chosen.length)return toast('Select a student in this teaching group.');if(star&&(chosen.length>2-lessonStar().length||chosen.some(s=>lessonAwards(s).some(a=>a.star))))return toast('A lesson can have at most two different stars. Each student can receive one star.');let affected=0,skip=0;for(const s of chosen){if(!star&&lessonAwards(s).some(a=>!a.star)){skip++;continue;}data.awards.push({id:uid(),sid:s.id,cat:star?'star':state.reason,amount:star?2:1,star,context:'lesson',lesson:lessonKey(),cls:state.cls,subject:lessonGroup().subject,date:state.date,period:state.period,time:Date.now(),operator:'Gary Talbot',note:star?'An outstanding positive contribution to the lesson.':''});affected++;}save();state.selected.clear();render();toast(`${affected} student${affected===1?'':'s'} received ${star?'Star of the Lesson (+2 extra points)':'a regular lesson point (+1)'}.${skip?' '+skip+' already had their regular point.':''}`)}
function leagues(){const s=student(),scope=state.league;let pool=scope==='class'?data.students.filter(x=>x.cls===(state.role==='student'?s.cls:state.leagueClass)):scope==='year'?data.students.filter(x=>x.year===(state.role==='student'?s.year:state.leagueYear)):data.students;const aggregate=scope!=='class'&&state.leagueMeasure==='classes';let rows=aggregate?[...new Set(pool.map(x=>x.cls))].map(cls=>{const group=pool.filter(x=>x.cls===cls),total=group.reduce((n,x)=>n+earned(x),0);return {id:cls,name:cls,cls,year:group[0].year,total,avg:total/group.length,count:group.length,stars:group.reduce((n,x)=>n+starCount(x),0)}}):pool.map(x=>({...x,total:earned(x),stars:starCount(x)}));rows.sort((a,b)=>(aggregate?b.avg-a.avg:b.total-a.total)||a.name.localeCompare(b.name));let own=rows.findIndex(x=>aggregate?x.cls===s.cls:x.id===s.id)+1;return heading('A little friendly competition.','Celebrate the effort across your class, your year and your school community.','<span class="chip">'+icon('trophy')+' Lifetime points · all time</span>')+`<div class="toolbar"><div class="tabs">${[['class','My class'],['year','Year group'],['school','Whole school']].map(([v,l])=>`<button class="${scope===v?'active':''}" data-action="league" data-value="${v}">${l}</button>`).join('')}</div><span class="spacer"></span>${scope!=='class'?`<select aria-label="League table type" data-change="leagueMeasure"><option value="students" ${!aggregate?'selected':''}>Student league</option><option value="classes" ${aggregate?'selected':''}>Class league</option></select>`:''}${state.role!=='student'&&scope==='class'?`<select aria-label="League class" data-change="leagueClass">${classes.map(c=>`<option ${c===state.leagueClass?'selected':''}>${c}</option>`).join('')}</select>`:''}${state.role!=='student'&&scope==='year'?`<select aria-label="League year group" data-change="leagueYear">${[7,8,9,10].map(y=>`<option value="${y}" ${y===state.leagueYear?'selected':''}>Year ${y}</option>`).join('')}</select>`:''}</div><div class="league-hero"><span>${icon('trophy')}</span><div><h3>${scope==='class'?(state.role==='student'?s.cls:state.leagueClass):scope==='year'?'Year '+(state.role==='student'?s.year:state.leagueYear):'The whole school community'}</h3><p>${state.role==='student'&&own?'You'+(aggregate?'r class is':'’re')+' #'+own+' in this league. ':''}${aggregate?'Classes rank by average lifetime points per student, so larger classes have no advantage.':'Every positive point adds to your place. Spending in the shop doesn’t change your ranking.'}</p></div></div><div class="card pad"><div class="section-head"><h2>${aggregate?'Class standings':'Student standings'}</h2><span class="sub">${rows.length} ${aggregate?'classes':'students'} · Years ${scope==='school'?'7–10':scope==='year'?(state.role==='student'?s.year:state.leagueYear):(state.role==='student'?s.year:parseInt(state.leagueClass))}</span></div><div class="table-wrap"><table class="league-table"><thead><tr><th>Rank</th><th>${aggregate?'Class':'Student'}</th><th>${aggregate?'Students':'Class'}</th><th>Stars</th><th>${aggregate?'Avg points':'Lifetime points'}</th></tr></thead><tbody>${rows.map((x,i)=>`<tr class="${(aggregate?x.cls===s.cls:x.id===s.id)&&state.role==='student'?'me':''}"><td>${i<3?`<span class="rank-medal ${i===1?'silver':i===2?'bronze':''}">${i+1}</span>`:`<span class="muted">${i+1}</span>`}</td><td><div class="league-name">${aggregate?'<span class="avatar">'+x.year+'</span>':avatar(x)}<b>${esc(x.name)}</b>${(aggregate?x.cls===s.cls:x.id===s.id)&&state.role==='student'?'<span class="you">'+(aggregate?'YOUR CLASS':'YOU')+'</span>':''}</div></td><td class="muted">${aggregate?x.count:x.cls}</td><td class="muted">☆ ${x.stars}</td><td><b style="color:#7c5c9e">${aggregate?x.avg.toFixed(1):x.total}</b> <span class="muted" style="font-size:9px">pts</span></td></tr>`).join('')}</tbody></table></div><p class="hint">Ties are ordered alphabetically. All scores are fictional demo data. Leagues count earned points, never unspent balances.</p></div>`}
function counter(){let s=student(state.shopStudent),p=products.find(p=>p.id===state.shopProduct),bal=wallet(s),can=bal>=p.price&&data.stock[p.id]>0;return heading('Cash in a student’s points.','Choose the student and their prize. Confirm the collection to deduct points from their account.','<span class="chip">'+icon('lock')+' '+(state.role==='teacher'?'Teacher shop access':'Shop operator demo')+'</span>')+`<div class="staff-links-strip">${state.role==='teacher'?'<button class="button outline" data-action="nav" data-value="teacherDashboard">← Teacher dashboard</button>':''}<span class="chip">${icon('info')} The deduction applies only to the selected student</span></div><div class="shop-layout"><div class="card pad"><h2>1. Find the student</h2><p class="hint">Ask the student for their name and tutor group.</p><div class="field"><label for="counter-student">STUDENT &amp; CLASS</label><select id="counter-student" data-change="shopStudent">${data.students.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${esc(x.name)} · ${x.cls}</option>`).join('')}</select></div><div class="student-summary">${avatar(s,true)}<div><h3>${esc(s.name)}</h3><span class="sub">${s.cls} · ${tiers[tierIndex(s)].name}</span></div><div class="wallet"><strong>${bal}</strong><small>points available</small></div></div><div class="section-head"><h2>2. Choose their reward</h2></div><div class="product-list">${products.map(x=>`<button class="product-pick ${p.id===x.id?'active':''}" data-action="counterProduct" data-value="${x.id}" aria-pressed="${p.id===x.id}">${rewardArt(x)}<div><h4>${x.name}</h4><small>${data.stock[x.id]} in stock</small></div><span class="points">${x.price} pts</span></button>`).join('')}</div><div class="checkout"><div class="between"><span>Available balance</span><b>${bal} pts</b></div><div class="between"><span>${p.name}</span><b>−${p.price} pts</b></div><div class="between" style="padding-top:12px;border-top:1px solid #e9dfef"><span>Balance after collection</span><b>${Math.max(0,bal-p.price)} pts</b></div>${!can?`<p>${bal<p.price?'Not enough points yet — '+(p.price-bal)+' more needed.':'This reward is out of stock.'}</p>`:'<p>Points are deducted only after you confirm. Their lifetime points and badges stay unchanged.</p>'}<button class="button" data-action="checkout" ${can?'':'disabled'}>${icon('check')} Review &amp; confirm collection</button></div></div><div class="stack"><div class="card pad"><div class="section-head"><h2>Recent shop collections</h2><span class="sub">${data.purchases.length} total</span></div>${data.purchases.length?data.purchases.slice().reverse().slice(0,10).map(x=>`<div class="history-row"><div class="between"><h4>${esc(student(x.sid).name)}</h4><b class="points">−${x.price} pts</b></div><p>${products.find(p=>p.id===x.pid).name} · ${student(x.sid).cls} · ${when(x.time)}</p><div class="between"><span class="sub" style="font-size:10px">Balance after: ${x.after} pts · Shop team</span><button class="text-button" data-action="refund" data-value="${x.id}">Reverse collection</button></div></div>`).join(''):'<div class="empty">No prizes collected yet.<br>Complete a demo collection to see the audit trail here.</div>'}</div><div class="card pad"><h2>At the counter</h2><div class="rule"><span class="rule-num">1</span><div><h4>Check the right student</h4><p>Match both the student’s name and class.</p></div></div><div class="rule"><span class="rule-num">2</span><div><h4>Check the prize together</h4><p>Read the points cost and remaining balance.</p></div></div><div class="rule"><span class="rule-num">3</span><div><h4>Confirm, then hand it over</h4><p>The deduction and stock change happen together. A mistaken collection can be reversed.</p></div></div></div></div></div>`}
function modal(title,body,actions=''){let d=$('#dialog');d.classList.remove('certificate-dialog');d.innerHTML=`<div class="modal"><div class="modal-top"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close dialog">✕</button></div>${body}${actions?'<div class="modal-actions">'+actions+'</div>':''}</div>`;d.showModal()}
function checkoutModal(){const s=student(state.shopStudent),p=products.find(p=>p.id===state.shopProduct);if(wallet(s)<p.price||data.stock[p.id]<1)return toast('Please check the balance and stock.');modal('Confirm their collection',`<p>You’re collecting this reward for <b>${esc(s.name)} · ${s.cls}</b>.</p>${rewardArt(p)}<div class="between"><b>${p.name}</b><span class="points">${p.price} points</span></div><p>Balance: <b>${wallet(s)} → ${wallet(s)-p.price} points</b><br>Lifetime points: <b>${earned(s)} — unchanged</b></p><p>Hand over the prize after confirming the collection.</p>`,'<button class="button outline" data-action="close">Go back</button><button class="button" data-action="confirmCheckout">Confirm collection</button>')}
function confirmCheckout(){let s=student(state.shopStudent),p=products.find(p=>p.id===state.shopProduct),before=wallet(s);if(before<p.price||data.stock[p.id]<1){$('#dialog').close();render();return toast('Balance or stock changed. Please check again.')}let unlockBefore=getBadges(s).filter(b=>b.count>=b.goal).length;data.purchases.push({id:uid(),sid:s.id,pid:p.id,price:p.price,before,after:before-p.price,time:Date.now(),operator:'Shop team'});data.stock[p.id]--;if(data.goals[s.id]===p.id)delete data.goals[s.id];save();$('#dialog').close();render();let unlocked=getBadges(s).filter(b=>b.count>=b.goal).length>unlockBefore;modal('Reward collected!',`<div class="center"><div class="success-seal">${icon('check')}</div><h3>${esc(s.name.split(' ')[0])} earned this.</h3><p>${p.name} · ${p.price} points spent<br><b>${wallet(s)} points left to save or spend</b></p>${unlocked?'<span class="chip">'+icon('award')+' New badge unlocked!</span>':''}<p>Please hand over the prize now.</p></div>`,'<button class="button full" data-action="close">Ready for the next student</button>')}
function guide(){return heading('How School Positives works.','Whole-school proposal for discussion. A possible Term 1, 2027 trial led by Science, with other subjects able to opt in.','<button class="button outline" data-action="reset">Reset fictional demo</button>')+`<div class="settings-grid"><div class="card pad"><h2>Lesson recognition</h2><p>Each student can receive one regular point per lesson. Star of the Lesson adds two extra points. Up to two students can be stars in the same lesson.</p><p><b>Maximum per student: 3 points in a lesson.</b> The star can be awarded before or after the regular point.</p></div><div class="card pad"><h2>Out-of-class positives</h2><p>Staff search across the school, select the correct name and tutor group, then record a reason and location. Each award is worth 1 or 2 points, up to a maximum of 2 per recognition event.</p><p>These awards are separate from the lesson allowance. Recognise a distinct event once.</p></div><div class="card pad"><h2>School-wide achievements</h2><p>Getting started, Positive contributor, Role model, School champion and Community ambassador recognise contributions across school.</p><p>Badges recognise effort, questions, helping others, progress and applying skills. Community spirit celebrates positives outside lessons.</p><p>Levels use lifetime points. Spending at the shop never removes achievements. The example thresholds need review before a trial.</p></div><div class="card pad"><h2>Leaders and families</h2><p>School leaders can explore the whole school. Heads of department have a subject view. Pastoral leaders have a year-group view.</p><p>Parents can switch between their linked children and see positive moments, reasons and achievements. The demo includes a family with two children and one with a single child.</p></div><div class="card pad"><h2>Workload and a trial</h2><p>SLT would need to agree which existing tasks stop or reduce, provide training in existing meeting time and allocate shop administration and support.</p><p>Science could trial with one year group in Term 1, 2027. Interested subjects could join with the same cohort, for example Year 9. Review staff time, fairness and student feedback before any expansion.</p></div><div class="card pad"><h2>About this demonstration</h2><p>All students and activity are fictional. The role switch demonstrates the proposed screens. This static prototype stores changes only in this browser.</p><p>It has no secure school or parent sign-in. A live system needs a shared database, verified child-to-parent links and server-enforced permissions and points limits.</p><p>Analysis counts recorded award events in the selected range, excluding fictional starting balances. League tables are optional and need a fairness review.</p></div></div>`}
function reset(){modal('Start the demo again?',`<p>This resets fictional points, prize collections and savings goals in this browser to their starting values.</p>`,'<button class="button outline" data-action="close">Keep exploring</button><button class="button danger" data-action="confirmReset">Reset demo data</button>')}
function teacherDashboard(){const date=localDate(),awards=data.awards.filter(a=>a.date===date),recent=data.awards.slice().sort((a,b)=>b.time-a.time).slice(0,5);return heading('Your whole-school recognition hub.','Choose a teaching group or recognise a positive contribution beyond the classroom.')+`<div class="hero teacher-dashboard-hero"><div class="hero-text"><div class="eyebrow">ST PETER’S · SCHOOL POSITIVES</div><h2>Everyday contributions.<br>Recognition across school.</h2><p>One regular lesson point. Two extra for a lesson star. Up to two points for a positive moment outside class.</p><div class="teacher-title-actions"><button class="button" data-action="openClass" data-value="${state.cls}">Award lesson points</button><button class="button outline" data-action="nav" data-value="outside">Recognise out-of-class behaviour</button></div></div>${guardian(2)}</div>${stats([['users','Students recognised today',new Set(awards.map(a=>a.sid)).size,'Across school in this demo'],['bolt','Points awarded today',awards.reduce((n,a)=>n+a.amount,0),'Lessons and wider school'],['star','Lesson stars today',awards.filter(a=>a.star).length,'Maximum two in each lesson']])}<div class="section-head"><h2>Teaching groups</h2><span class="sub">${data.students.length} fictional students · Years 7–10</span></div><div class="teacher-class-grid">${teachingGroups.map(g=>`<article class="card teacher-class-card"><div class="class-identity"><span>${parseInt(g.id)}</span><div><h3>${g.id}</h3><small>${g.subject} · Tutor group ${g.home}</small></div></div><p>${data.students.filter(s=>s.cls===g.home).length} students</p><button class="button" data-action="openClass" data-value="${g.id}">Open lesson</button></article>`).join('')}</div><div class="card pad mt"><h2>Recent recognition across school</h2>${recent.map(a=>`<div class="activity-row"><span class="activity-icon">${icon(a.star?'star':'award')}</span><div><h4>${esc(student(a.sid).name)} · ${a.star?'Star of the Lesson':cats.find(c=>c.id===a.cat)?.name}</h4><small>${a.context==='outside'?esc(a.location):esc(a.subject)} · ${when(a.time)}</small></div><b class="delta">+${a.amount}</b></div>`).join('')}</div>`}
function navigate(page){state.page=page;state.search='';render();window.scrollTo({top:0,behavior:'instant'})}
function role(r){if(!navByRole[r])return;state.role=r;state.page=navByRole[r][0][0];history.replaceState(null,'','#'+r);state.selected.clear();state.search='';render();window.scrollTo({top:0,behavior:'instant'})}
function localDate(time=Date.now()){return new Date(time).toLocaleDateString('en-CA',{timeZone:'Pacific/Auckland'})}
function lessonGroup(){return teachingGroups.find(g=>g.id===state.cls)}
function rosterForLesson(){const g=lessonGroup();return g?data.students.filter(s=>s.cls===g.home):[]}
const families={morgan:{name:'Morgan family',parent:'Sam Morgan',children:['s48','s84']},singh:{name:'Singh family',parent:'Taylor Singh',children:['s72']}};
function option(value,label,current){return `<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`}
function field(label,id,body){return `<div class="field"><label for="${id}">${label}</label>${body}</div>`}
function outside(){const q=state.outsideSearch.trim().toLowerCase(),matches=q?data.students.filter(s=>(s.name+' '+s.cls).toLowerCase().includes(q)):[],s=student(state.outsideStudent),recent=data.awards.filter(a=>a.context==='outside').slice().sort((a,b)=>b.time-a.time).slice(0,8);return heading('Positive moments beyond the classroom.','Search the school roster and recognise a distinct positive event. Up to 2 points per award.')+`<div class="grid2"><section class="card pad"><h2>Find the right student</h2><label for="outside-search">Student name or tutor group</label><input id="outside-search" class="full" type="search" data-input="outsideSearch" value="${esc(state.outsideSearch)}" placeholder="Try Alex Morgan or 9A" autocomplete="off"><p class="hint">All ${data.students.length} fictional students are searchable. Match both the name and tutor group.</p><div class="outside-results">${matches.map(x=>`<button class="student-result ${x.id===state.outsideStudent?'selected':''}" data-action="outsidePick" data-value="${x.id}">${avatar(x)}<span><b>${esc(x.name)}</b><small>Year ${x.year} · ${x.cls}</small></span>${x.id===state.outsideStudent?icon('check'):''}</button>`).join('')||`<p class="empty">${q?'No student matches. Try a first name or tutor group.':'Start typing to search across school.'}</p>`}</div></section><section class="card pad"><h2>Record the positive</h2>${s?`<div class="selected-student">${avatar(s)}<div><h3>${esc(s.name)}</h3><p>Year ${s.year} · ${s.cls}</p></div></div>`:'<p class="hint">Select a student from the search results.</p>'}<div class="form-stack">${field('Reason','outside-reason',`<select id="outside-reason" data-change="outsideReason">${cats.map(c=>option(c.id,c.name,state.outsideReason)).join('')}</select>`)}${field('Location','outside-location',`<select id="outside-location" data-change="outsideLocation">${['School grounds','Library','Dining hall','Corridor','School event','Other school setting'].map(l=>option(l,l,state.outsideLocation)).join('')}</select>`)}${field('Points','outside-amount',`<select id="outside-amount" data-change="outsideAmount">${option(1,'1 point',state.outsideAmount)}${option(2,'2 points (maximum)',state.outsideAmount)}</select>`)}${field('What did they do?','outside-note',`<textarea id="outside-note" data-input="outsideNote" maxlength="180" rows="3" placeholder="A short positive message for the student and family">${esc(state.outsideNote)}</textarea>`)}<button class="button full" data-action="outsideAward" ${s?'':'disabled'}>Award ${state.outsideAmount} positive point${state.outsideAmount==='1'?'':'s'}</button><p class="hint">Separate from lesson points. Record each distinct event once. The short message also appears in the family view.</p></div></section></div><section class="card pad mt"><h2>Recent out-of-class recognition</h2>${recent.map(a=>`<div class="activity-row"><span class="activity-icon">${icon('heart')}</span><div><h4>${esc(student(a.sid).name)} · ${student(a.sid).cls}</h4><p>${esc(a.note)}</p><small>${esc(a.location)} · ${when(a.time)} · ${esc(a.operator)}</small></div><b class="delta">+${a.amount}</b><button class="text-button" data-action="undoAward" data-value="${a.id}">Undo</button></div>`).join('')||'<p class="empty">No out-of-class positives yet.</p>'}</section>`}
function awardOutside(){if(!['teacher','admin'].includes(state.role))return toast('Use a staff demo account.');const s=student(state.outsideStudent),amount=Number(state.outsideAmount),note=state.outsideNote.trim();if(!s)return toast('Select a student first.');if(![1,2].includes(amount))return toast('An out-of-class award can be 1 or 2 points.');if(!note)return toast('Add a short positive message about this event.');if(note.length>180||!cats.some(c=>c.id===state.outsideReason))return toast('Check the award details.');const date=localDate();if(data.awards.some(a=>a.context==='outside'&&a.sid===s.id&&a.date===date&&a.note===note&&a.location===state.outsideLocation))return toast('That event has already been recognised today.');data.awards.push({id:uid(),sid:s.id,cat:state.outsideReason,amount,star:false,context:'outside',lesson:`outside|${date}|${uid()}`,subject:'Wider school',date,period:'',location:state.outsideLocation,note,time:Date.now(),operator:state.role==='admin'?'Pastoral leader':'Gary Talbot'});save();state.outsideNote='';render();toast(`${s.name} received ${amount} point${amount===1?'':'s'} for their positive contribution.`)}
function scopedStudents(){return data.students.filter(s=>state.adminRole!=='pastoral'||s.year===Number(state.adminYear)).filter(s=>state.adminRole!=='department'||teachingGroups.some(g=>g.subject===state.adminSubject&&g.home===s.cls)).filter(s=>state.filterYear==='all'||s.year===Number(state.filterYear))}
function analysisAwards(){const ids=new Set(scopedStudents().map(s=>s.id));return data.awards.filter(a=>ids.has(a.sid)&&(state.adminRole!=='department'||a.subject===state.adminSubject)&&(state.filterSubject==='all'||a.subject===state.filterSubject)&&(state.filterContext==='all'||a.context===state.filterContext)&&(!state.filterFrom||a.date>=state.filterFrom)&&(!state.filterTo||a.date<=state.filterTo))}
function analytics(){const awards=analysisAwards(),pool=scopedStudents(),recognised=new Set(awards.map(a=>a.sid)),points=awards.reduce((n,a)=>n+a.amount,0),subjects=[...new Set(teachingGroups.map(g=>g.subject)),'Wider school'],scope=state.adminRole==='department'?state.adminSubject+' department':state.adminRole==='pastoral'?'Year '+state.adminYear+' pastoral':'Whole school';const group=key=>{const m=new Map();awards.forEach(a=>{const k=key(a),x=m.get(k)||{name:k,count:0,points:0};x.count++;x.points+=a.amount;m.set(k,x)});return [...m.values()].sort((a,b)=>b.points-a.points)};const summary=(title,rows)=>`<section class="card pad"><h2>${title}</h2>${rows.length?`<table class="analysis-table"><thead><tr><th>Group</th><th>Awards</th><th>Points</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${esc(r.name)}</th><td>${r.count}</td><td>${r.points}</td></tr>`).join('')}</tbody></table>`:'<p class="empty">No matching awards.</p>'}</section>`;const byStudent=pool.map(s=>{const aa=awards.filter(a=>a.sid===s.id);return {s,count:aa.length,points:aa.reduce((n,a)=>n+a.amount,0)}}).sort((a,b)=>b.points-a.points||a.s.name.localeCompare(b.s.name));return heading('Recognition across your school.','Explore who receives recognition, where it happens and how consistently the system is used.','<button class="button outline" data-action="exportAnalysis">Download filtered CSV</button>')+`<div class="card pad mb"><h2>Demo leader access</h2><div class="filters">${field('Leader role','admin-role',`<select id="admin-role" data-change="adminRole">${[['school','School leader'],['department','Head of department'],['pastoral','Pastoral leader']].map(([v,l])=>option(v,l,state.adminRole)).join('')}</select>`)}${state.adminRole==='department'?field('Department','admin-subject',`<select id="admin-subject" data-change="adminSubject">${subjects.filter(s=>s!=='Wider school').map(s=>option(s,s,state.adminSubject)).join('')}</select>`):''}${state.adminRole==='pastoral'?field('Pastoral year group','admin-year',`<select id="admin-year" data-change="adminYear">${[7,8,9,10].map(y=>option(y,'Year '+y,state.adminYear)).join('')}</select>`):''}<span class="chip">${scope}</span></div><p class="hint">Scope demonstration with fictional records. Live roles would come from verified school accounts.</p></div><div class="card pad mb"><div class="filters">${field('Year group','filter-year',`<select id="filter-year" data-change="filterYear">${option('all','All available years',state.filterYear)}${[7,8,9,10].map(y=>option(y,'Year '+y,state.filterYear)).join('')}</select>`)}${field('Subject','filter-subject',`<select id="filter-subject" data-change="filterSubject">${option('all','All available subjects',state.filterSubject)}${subjects.map(x=>option(x,x,state.filterSubject)).join('')}</select>`)}${field('Context','filter-context',`<select id="filter-context" data-change="filterContext">${[['all','All contexts'],['lesson','In lessons'],['outside','Out of class']].map(([v,l])=>option(v,l,state.filterContext)).join('')}</select>`)}${field('From','filter-from',`<input id="filter-from" type="date" data-change="filterFrom" value="${state.filterFrom}">`)}${field('To','filter-to',`<input id="filter-to" type="date" data-change="filterTo" value="${state.filterTo}">`)}</div></div>${state.filterFrom&&state.filterTo&&state.filterFrom>state.filterTo?'<p class="banner">The start date is after the end date. Change the date range.</p>':''}${stats([['bolt','Points recorded',points,awards.length+' award events'],['users','Students recognised',recognised.size+' / '+pool.length,(pool.length?Math.round(recognised.size/pool.length*100):0)+'% of selected cohort'],['star','Lesson stars',awards.filter(a=>a.star).length,'Within the selected filters']])}<p class="hint">Counts use recorded awards, excluding fictional starting balances. Cohort = students within the leader and year scope. Different lesson access and attendance can affect comparisons.</p><div class="settings-grid">${summary('Recognition by subject',group(a=>a.subject))}${summary('Recognition by reason',group(a=>a.star?'Star of the Lesson':cats.find(c=>c.id===a.cat)?.name||'Positive'))}${summary('Recognition by context',group(a=>a.context==='outside'?'Out of class':'In lessons'))}${summary('Staff recording activity',group(a=>a.operator))}</div><section class="card pad mt"><h2>Student recognition in this view</h2><p>${pool.length-recognised.size} students have no recorded award in the selected range. Use this to check opportunities for recognition.</p><div class="table-wrap"><table class="analysis-table"><thead><tr><th>Student</th><th>Tutor group</th><th>Awards</th><th>Points</th></tr></thead><tbody>${byStudent.map(x=>`<tr><th>${esc(x.s.name)}</th><td>${x.s.cls}</td><td>${x.count}</td><td>${x.points}</td></tr>`).join('')}</tbody></table></div></section>`}
function exportAnalysis(){if(state.role!=='admin')return;const rows=[['Date','Student','Tutor group','Subject','Context','Reason','Points','Staff'],...analysisAwards().map(a=>[a.date,student(a.sid).name,student(a.sid).cls,a.subject,a.context==='outside'?'Out of class':'Lesson',a.star?'Star of the Lesson':cats.find(c=>c.id===a.cat)?.name,a.amount,a.operator])];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='School-Positives-Analysis.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function parentView(){const family=families[state.family],children=family.children.map(id=>student(id));if(!family.children.includes(state.parentChild))state.parentChild=family.children[0];const s=student(state.parentChild),level=tiers[tierIndex(s)],badges=getBadges(s).filter(b=>b.count>=b.goal),awards=data.awards.filter(a=>a.sid===s.id),latest=awards.slice().sort((a,b)=>b.time-a.time)[0];return heading('Their positive moments, shared with you.',`Welcome, ${esc(family.parent)}. See recognition for your ${children.length===1?'child':'children'} across lessons and the wider school.`,field('Demo family','family-switch',`<select id="family-switch" data-change="family">${Object.entries(families).map(([id,f])=>option(id,f.name+' · '+f.children.length+' child'+(f.children.length===1?'':'ren'),state.family)).join('')}</select>`))+`<div class="family-children" aria-label="Your linked children">${children.map(c=>`<button class="child-card ${c.id===s.id?'active':''}" data-action="parentChild" data-value="${c.id}" aria-pressed="${c.id===s.id}">${avatar(c)}<span><b>${esc(c.name)}</b><small>Year ${c.year} · ${c.cls}</small></span></button>`).join('')}</div><div class="hero parent-hero"><div class="hero-text"><div class="eyebrow">${esc(s.name)} · ${s.cls}</div><h2>${level.name}</h2><p>${level.power} Recognition from every participating subject adds to this shared record.</p></div>${guardian(tierIndex(s))}</div>${stats([['award','Lifetime recognition',earned(s),'Points earned across school'],['star','Achievements unlocked',badges.length,'Badges recognise different contributions'],['heart','Latest positive',latest?when(latest.time):'None yet',latest?(latest.context==='outside'?'Beyond the classroom':latest.subject):'Positive moments will appear below']])}<div class="grid2"><section class="card pad"><h2>${esc(s.name.split(' ')[0])}’s positives</h2><p class="hint">Reasons, positive messages and the staff who recognised them.</p>${activity(s,Number.MAX_SAFE_INTEGER,true)}</section><section class="card pad"><h2>Achievements to celebrate</h2><div class="parent-badges">${badges.map(b=>`<div class="activity-row">${badgeToken(b)}<div><h3>${b.name}</h3><p>${b.desc}</p></div></div>`).join('')||'<p>New achievements will appear as positive contributions build.</p>'}</div><h3 class="mt">A shared picture of progress</h3><p>Lesson positives are worth 1 point. Star of the Lesson adds 2 extra, with up to two stars per lesson. Out-of-class awards are worth up to 2 points.</p><p class="hint">This view includes only this demo family’s linked children. It does not show other students, public rankings or internal leader analysis.</p></section></div>`}

document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,v=el.dataset.value;switch(action){case'certPreview':previewCertificates([v]);break;case'certBatch':previewCertificates(filteredCertificates().filter(r=>!r.record).map(r=>r.key));break;case'printCertificates':printCertificates();break;case'markCertificatesPrinted':markCertificatesPrinted();break;case'openClass':state.cls=v;state.selected.clear();navigate('classroom');break;case'nav':navigate(v);break;case'role':role(v);break;case'guide':navigate('guide');break;case'selectStudent':state.selected.has(v)?state.selected.delete(v):state.selected.add(v);render();break;case'selectAll':rosterForLesson().filter(s=>true&&s.name.toLowerCase().includes(state.search.toLowerCase())).forEach(s=>state.selected.add(s.id));render();break;case'clear':state.selected.clear();render();break;case'reason':state.reason=v;render();break;case'outsidePick':state.outsideStudent=v;render();break;case'outsideAward':awardOutside();break;case'parentChild':if(families[state.family].children.includes(v)){state.parentChild=v;render()}break;case'exportAnalysis':exportAnalysis();break;case'award':award();break;case'star':award(true);break;case'undoAward':{let a=data.awards.find(x=>x.id===v);if(!a)return;let s=student(a.sid);if(wallet(s)<a.amount)return toast('These points have been spent. Reverse the relevant shop collection first.');data.awards=data.awards.filter(x=>x.id!==v);save();render();toast('Award undone. Balance, lesson total and achievements recalculated.');break}case'goal':data.goals[state.student]=v;save();render();toast('Savings goal set. Visit the lunchtime school shop when you’re ready to collect.');break;case'badgeFilter':state.badgeFilter=v;render();break;case'rewardFilter':state.rewardFilter=v;render();break;case'league':state.league=v;render();break;case'counterProduct':state.shopProduct=v;render();break;case'shopPick':state.shopProduct=v;navigate('counter');break;case'prizeInfo':{let p=products.find(p=>p.id===v);modal(p.name,rewardArt(p)+`<p>${p.desc}</p><p><b>${p.price} points</b> · ${data.stock[p.id]} in stock<br>Example prize for discussion with the school.</p>`,'<button class="button" data-action="close">Done</button>');break}case'checkout':checkoutModal();break;case'confirmCheckout':confirmCheckout();break;case'refund':{let p=data.purchases.find(x=>x.id===v);if(!p)return;modal('Reverse this collection?',`<p>Return <b>${p.price} points</b> to <b>${esc(student(p.sid).name)}</b> and put one <b>${products.find(x=>x.id===p.pid).name}</b> back in stock. Please recover the physical prize too.</p>`,`<button class="button outline" data-action="close">Go back</button><button class="button" data-action="confirmRefund" data-value="${v}">Reverse collection</button>`);break}case'confirmRefund':{let p=data.purchases.find(x=>x.id===v);if(!p)return;data.stock[p.pid]++;data.purchases=data.purchases.filter(x=>x.id!==v);save();$('#dialog').close();render();toast('Collection reversed. Points returned and stock restored.');break}case'close':$('#dialog').close();break;case'reset':reset();break;case'confirmReset':data=seed();save();state.selected.clear();$('#dialog').close();render();toast('Demo reset. Ready for your presentation.');break}});
document.addEventListener('change',e=>{let k=e.target.dataset.change,v=e.target.value;if(!k)return;if(k==='family'){state.family=v;state.parentChild=families[v].children[0];}else if(k==='student'){state.student=v;state.leagueClass=student(v).cls;state.leagueYear=student(v).year;}else if(['cls','period','date'].includes(k)){if(k==='date'&&!v){e.target.value=state.date;return toast('A lesson needs a date.')}state[k]=v;state.selected.clear();}else if(k==='certYear'){state.certYear=v;state.certClass='all';}else if(k==='leagueYear')state[k]=Number(v);else state[k]=v;render()});
document.addEventListener('input',e=>{if(['outsideSearch','outsideNote'].includes(e.target.dataset.input)){const key=e.target.dataset.input,pos=e.target.selectionStart;state[key]=e.target.value;if(key==='outsideNote')return;render();const input=document.querySelector('[data-input="'+key+'"]');input.focus();input.setSelectionRange(pos,pos);return;}if(e.target.id==='cert-search'){const pos=e.target.selectionStart;state.certSearch=e.target.value;render();const input=$('#cert-search');input.focus();input.setSelectionRange(pos,pos);return;}if(e.target.dataset.input==='rosterSearch'){let start=e.target.selectionStart;state.search=e.target.value;render();let input=$('[data-input="rosterSearch"]');input.focus();try{input.setSelectionRange(start,start)}catch{}}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){let rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)e.target.close()}});
const initialRole=location.hash.slice(1);if(navByRole[initialRole]){state.role=initialRole;state.page=navByRole[initialRole][0][0];}
render();
